import 'package:flutter/material.dart';import '../theme/app_theme.dart';
class StaffScreen extends StatefulWidget{const StaffScreen({super.key});@override State<StaffScreen> createState()=>_StaffScreenState();}
class _StaffScreenState extends State<StaffScreen>{int tab=0;final hired=<String>[];final roles=['Sopir','Mekanik','Manajer'];final people=[['Raka Pratama','Dimas Saputra','Arif Nugroho'],['Bima Teknisi','Rendi Maulana','Yoga Firmansyah'],['Nadia Putri','Salsa Maharani','Kevin Wijaya']];@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(14),children:[Row(children:List.generate(3,(i)=>Expanded(child(Padding(padding:const EdgeInsets.only(right:5),child(ChoiceChip(label:Text(roles[i]),selected:tab==i,onSelected:(_)=>setState(()=>tab=i))))))),Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:AppColors.surface,borderRadius:BorderRadius.circular(13)),child:Text('Manajemen SDM • '+hired.length.toString()+' staf direkrut',style:const TextStyle(fontWeight:FontWeight.w900))),const SizedBox(height:12),const Text('KANDIDAT TERSEDIA',style:TextStyle(color:AppColors.textSecondary,fontWeight:FontWeight.w900,fontSize:10)),...List.generate(3,(i)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(people[tab][i]),subtitle:Text('Skill '+(4+i).toString()+'/5 • bonus '+(5+i*3).toString()+'%\nGaji harian $'+(180+i*35).toString()),trailing:FilledButton(onPressed:()=>setState(()=>hired.add(people[tab][i])),child:const Text('Rekrut'))))),const SizedBox(height:12),const Text('STAF PERUSAHAAN',style:TextStyle(color:AppColors.textSecondary,fontWeight:FontWeight.w900,fontSize:10)),if(hired.isEmpty)const Text('Belum ada staf direkrut.',style:TextStyle(color:AppColors.textSecondary))else ...hired.map((n)=>ListTile(title:Text(n),subtitle:const Text('Penugasan kendaraan belum ditetapkan'),trailing:IconButton(onPressed:()=>setState(()=>hired.remove(n)),icon:const Icon(Icons.person_remove,color:AppColors.danger))))]);}